class Solution {
    public int[] findErrorNums(int[] nums) {
        int dup = -1, missing = -1;
        for (int n : nums) {
            int idx = Math.abs(n) - 1;
            if (nums[idx] < 0) dup = Math.abs(n);
            else nums[idx] = -nums[idx];
        }
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > 0) missing = i + 1;
        }
        return new int[]{dup, missing};
    }
}

class Solution {
    public int[] findErrorNums(int[] nums) {
        int n = nums.length;
        long sumDiff = 0, sqDiff = 0;
        for (int i = 0; i < n; i++) {
            sumDiff += nums[i] - (i + 1);
            sqDiff += (long) nums[i] * nums[i] - (long) (i + 1) * (i + 1);
        }
        long sumAB = sqDiff / sumDiff;
        int dup = (int) ((sumDiff + sumAB) / 2);
        int missing = (int) ((sumAB - sumDiff) / 2);
        return new int[]{dup, missing};
    }
}
